package cel_test

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"

	"github.com/ornew/zeroparse/internal/corpora/corporatest"
	"github.com/ornew/zeroparse/parsers/cel"
	"github.com/ornew/zeroparse/parsers/cel/internal/upstream"
)

// refDir is the directory of the reference results of cel-go: testdata/ref, or the directory that the environment
// variable CEL_REF_DIR names, which is where a larger set generated by internal/refgen goes.
func refDir() string {
	if d := os.Getenv("CEL_REF_DIR"); d != "" {
		return d
	}
	return filepath.Join("testdata", "ref")
}

// refCounts are the numbers of cases of the files of testdata/ref, which the tests require: a file that lost lines
// must not pass with fewer cases. (CEL_REF_DIR names other files, which are not counted.)
var refCounts = map[string]int{
	"celgo.tsv": 358, "conformance.tsv": 2263, "deep.tsv": 1000, "edge.tsv": 854, "literals.tsv": 4000,
	"macros.tsv": 12319, "random.tsv": 12000,
}

// upstreamTexts maps the hash of each expression of the conformance tests of cel-spec and of the tests of cel-go's
// parser to the expression: the result files refer to those expressions by hash and hold no text of the projects. The
// test is skipped if the sources are not fetched. conformance has the expressions of cel-spec only.
var (
	upstreamOnce        sync.Once
	upstreamAll         map[string]string
	upstreamConformance map[string]bool
)

func upstreamTexts(t testing.TB) map[string]string {
	t.Helper()
	spec, celgo := corporatest.Dir(t, "cel-spec"), corporatest.Dir(t, "cel-go")
	upstreamOnce.Do(func() {
		conf, err := upstream.ConformanceExprs(spec)
		if err != nil {
			t.Fatal(err)
		}
		goTests, err := upstream.GoTestInputs(filepath.Join(celgo, "parser"))
		if err != nil {
			t.Fatal(err)
		}
		upstreamAll, upstreamConformance = map[string]string{}, map[string]bool{}
		for _, s := range conf {
			upstreamAll[upstream.Hash(s)] = s
			upstreamConformance[upstream.Hash(s)] = true
		}
		for _, s := range goTests {
			upstreamAll[upstream.Hash(s)] = s
		}
	})
	if upstreamAll == nil {
		t.Fatal("reading the fetched sources failed")
	}
	return upstreamAll
}

// refCase is a line of testdata/ref/*.tsv: an expression and what cel-go makes of it (see internal/refgen). The
// expression is a Go string literal, or for text of cel-spec and cel-go the hash that upstream.Hash makes of it.
type refCase struct {
	src, want string
}

func readRef(t testing.TB, name string) []refCase {
	t.Helper()
	f, err := os.Open(filepath.Join(refDir(), name))
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	var cases []refCase
	sc := bufio.NewScanner(f)
	sc.Buffer(nil, 1<<24)
	for sc.Scan() {
		q, want, ok := strings.Cut(sc.Text(), "\t")
		if !ok {
			t.Fatalf("%s: bad line %.60q", name, sc.Text())
		}
		var src string
		if strings.HasPrefix(q, "sha256:") {
			var ok bool
			if src, ok = upstreamTexts(t)[q]; !ok {
				t.Fatalf("%s: no expression of cel-spec or cel-go has the hash in %.60q", name, sc.Text())
			}
			if name == "conformance.tsv" && !upstreamConformance[q] {
				t.Fatalf("%s: %q is not an expression of cel-spec", name, src)
			}
		} else {
			var err error
			if src, err = strconv.Unquote(q); err != nil {
				t.Fatalf("%s: bad line %.60q: %v", name, sc.Text(), err)
			}
		}
		cases = append(cases, refCase{src, want})
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	if len(cases) == 0 {
		t.Fatalf("%s: no cases", name)
	}
	if name == "conformance.tsv" && len(cases) != len(upstreamConformance) {
		t.Fatalf("%s: %d cases, but cel-spec has %d different expressions", name, len(cases), len(upstreamConformance))
	}
	if want, ok := refCounts[name]; ok && os.Getenv("CEL_REF_DIR") == "" && len(cases) != want {
		t.Fatalf("%s: %d cases, want %d", name, len(cases), want)
	}
	return cases
}

// result parses src as ParseExpr does and returns the canonical form of the expression, or ERR@line:column of
// the error (the columns of cel-go count from 1 as well).
func result(src string, opts ...cel.Option) string {
	e, err := cel.ParseExpr(src, opts...)
	if err != nil {
		var se *cel.SyntaxError
		var ce *cel.CheckError
		switch {
		case errors.As(err, &se):
			return fmt.Sprintf("ERR@%d:%d", se.Line, se.Col)
		case errors.As(err, &ce):
			return fmt.Sprintf("ERR@%d:%d", ce.Line, ce.Col)
		}
		return "ERR"
	}
	return canonical(src, e)
}

// TestDifferential compares the AST of every expression of testdata/ref/*.tsv with the one cel-go returns for it
// (and the rejected ones with the errors of cel-go): the conformance tests of cel-spec, the cases of cel-go's own
// parser tests, hand-picked edge cases, and random expressions and literals.
func TestDifferential(t *testing.T) {
	files, _ := filepath.Glob(filepath.Join(refDir(), "*.tsv"))
	for _, f := range files {
		name := filepath.Base(f)
		if name == "limits.tsv" {
			continue
		}
		t.Run(strings.TrimSuffix(name, ".tsv"), func(t *testing.T) {
			var opts []cel.Option
			if name == "macros.tsv" { // cel-go with the standard macros
				opts = append(opts, cel.WithMacros())
			}
			bad, rejected, samePos := 0, 0, 0
			for _, c := range readRef(t, name) {
				got := result(c.src, opts...)
				gotErr, wantErr := strings.HasPrefix(got, "ERR"), strings.HasPrefix(c.want, "ERR")
				if c.want == "OK" && !gotErr { // a file of verdicts: the tree is not compared
					got = "OK"
				}
				switch {
				case gotErr && wantErr: // the position of the error is not required to be the same
					rejected++
					if got == c.want {
						samePos++
					}
				case got != c.want:
					bad++
					if bad <= 12 {
						t.Errorf("%.300q\n got  %.300s\n want %.300s", c.src, got, c.want)
					}
				}
			}
			if bad > 12 {
				t.Errorf("%d differences in all", bad)
			}
			if rejected > 0 {
				t.Logf("%d rejected, the first error at the same position as cel-go's in %d (%.1f%%)", rejected, samePos, 100*float64(samePos)/float64(rejected))
			}
		})
	}
}
